'use strict';
// Três campanhas novas. IDs existentes e progresso das missões anteriores permanecem estáveis.
MISSIONS.push(
  {id:'campanha-matriculas',title:'Matrículas sem duplicatas',en:'Enrollment without duplicates',summary:'Construa uma rotina com validação, coleção e relatório.',summaryEn:'Validation, collections and report.',icon:'boxes',color:'#6a9ec9',steps:[
    arenaStep('Validar idade','A secretaria não pode aprovar idade negativa.','Crie validar(int idade) que lance IllegalArgumentException para valor negativo; trate o erro e imprima Idade inválida.',`public class Main {\n  static void validar(int idade) {\n    // Lance a exceção se for negativo.\n  }\n  public static void main(String[] args) {\n    try { validar(-2); } catch (IllegalArgumentException e) { System.out.println("Idade inválida"); }\n  }\n}`,'Idade inválida',/throw\s+new\s+IllegalArgumentException/,['A regra entra no método validar.','Teste idade < 0.','Use throw new IllegalArgumentException().'],'Uma validação é uma catraca que barra dados impossíveis.'),
    arenaStep('Remover duplicatas','Nomes repetidos chegaram em uma lista.','Use LinkedHashSet para imprimir Ana, Bia, Caio nessa ordem, uma pessoa por linha.',missionWrap('    String[] nomes = {"Ana", "Bia", "Ana", "Caio"};\n    // Preserve a ordem de chegada sem repetições.'),'Ana\nBia\nCaio',/LinkedHashSet/,['Importe java.util.LinkedHashSet ou use o nome completo.','Adicione cada nome no conjunto.','Percorra o conjunto com for-each.'],'Uma lista de presença só admite uma entrada por pessoa.'),
    arenaStep('Buscar com Optional','Um cadastro pode não encontrar a pessoa.','Crie um Optional<String> vazio e imprima Não encontrado usando orElse.',`import java.util.Optional;\npublic class Main {\n  public static void main(String[] args) {\n    Optional<String> aluno = Optional.empty();\n    // Trate a ausência sem chamar get().\n  }\n}`,'Não encontrado',/\.orElse\s*\(/,['Optional guarda presença ou ausência.','Chame aluno.orElse("Não encontrado").','Imprima o resultado.'],'O Optional é uma caixa que pode vir vazia com uma resposta alternativa.'),
    arenaStep('Relatório com Stream','A turma tem notas 4, 7, 9 e 6.','Use Arrays.stream, filter e count para imprimir Aprovados: 3.',`import java.util.Arrays;\npublic class Main {\n  public static void main(String[] args) {\n    int[] notas = {4, 7, 9, 6};\n    // Conte apenas notas >= 6.\n  }\n}`,'Aprovados: 3',/Arrays\.stream[\s\S]*\.filter[\s\S]*\.count/,['Comece com Arrays.stream(notas).','Filtre n -> n >= 6.','Use count() e imprima com o prefixo.'],'O filtro deixa passar só quem atende à regra.')
  ]},
  {id:'campanha-financas',title:'Carteira precisa',en:'Precise wallet',summary:'Trate valores monetários, datas e arquivo de relatório.',summaryEn:'Money, dates and reporting file.',icon:'file',color:'#ad7bc4',steps:[
    arenaStep('Centavos exatos','Uma soma com double pode perder precisão.','Some 0.10 e 0.20 com BigDecimal construído de String e imprima 0.30.',`import java.math.BigDecimal;\npublic class Main {\n  public static void main(String[] args) {\n    // Crie dois BigDecimal(String) e some.\n  }\n}`,'0.30',/BigDecimal[\s\S]*\.add\s*\(/,['Passe "0.10" e "0.20" no construtor.','Chame add.','Imprima o BigDecimal diretamente.'],'Dinheiro pede uma régua decimal, não aproximação binária.'),
    arenaStep('Prazo de pagamento','Um boleto vence três dias após 2026-10-01.','Use LocalDate e plusDays para imprimir 2026-10-04.',`import java.time.LocalDate;\npublic class Main {\n  public static void main(String[] args) {\n    LocalDate emissao = LocalDate.parse("2026-10-01");\n    // Calcule o vencimento.\n  }\n}`,'2026-10-04',/\.plusDays\s*\(/,['LocalDate é imutável.','Guarde emissao.plusDays(3).','Imprima a nova data.'],'Uma data nova é uma página nova no calendário.'),
    arenaStep('Registrar lançamento','A equipe quer gerar e reler um relatório.','Use Files.writeString e Files.readString em um arquivo temporário para imprimir Saldo: 25.',`import java.nio.file.*;\npublic class Main {\n  public static void main(String[] args) throws Exception {\n    Path relatorio = Files.createTempFile("saldo", ".txt");\n    try {\n      // Grave e leia "Saldo: 25".\n    } finally { Files.deleteIfExists(relatorio); }\n  }\n}`,'Saldo: 25',/Files\.writeString[\s\S]*Files\.readString/,['Grave no Path com Files.writeString.','Leia o mesmo Path com Files.readString.','O finally remove o arquivo temporário.'],'O arquivo é uma memória externa, lida depois da gravação.'),
    arenaStep('Ordenar lançamentos','A equipe recebeu valores 5, 18 e 9.','Use Arrays.sort para imprimir 5, 9, 18 em linhas separadas.',`import java.util.Arrays;\npublic class Main {\n  public static void main(String[] args) {\n    int[] valores = {5, 18, 9};\n    // Ordene e percorra.\n  }\n}`,'5\n9\n18',/Arrays\.sort[\s\S]*\bfor\s*\(/,['Arrays.sort organiza o array in-place.','Depois use for-each.','Imprima cada valor.'],'Ordenar é colocar recibos em sequência.'),
  ]},
  {id:'campanha-atendimento',title:'Central de atendimento',en:'Support desk',summary:'Modele chamados com record, estados, eventos e testes simples.',summaryEn:'Model tickets with record, states and simple tests.',icon:'terminal',color:'#dc906c',steps:[
    arenaStep('Chamado imutável','Um ticket guarda número e assunto.','Defina record Ticket(int id, String assunto), crie Ticket(7, "Login") e imprima #7 Login.',`record Ticket(int id, String assunto) {}\npublic class Main {\n  public static void main(String[] args) {\n    // Instancie e leia os componentes do record.\n  }\n}`,'#7 Login',/record\s+Ticket[\s\S]*\.assunto\s*\(/,['Use new Ticket(7, "Login").','Acesse id() e assunto().','Formate "#" + t.id() + " " + t.assunto().'],'Um record é uma ficha curta com dados definidos.'),
    arenaStep('Estado do chamado','O chamado pode ficar ABERTO ou RESOLVIDO.','Crie enum Estado com esses dois valores e imprima RESOLVIDO.',`enum Estado {\n  // Declare os estados.\n}\npublic class Main {\n  public static void main(String[] args) {\n    // Imprima o estado final.\n  }\n}`,'RESOLVIDO',/enum\s+Estado[\s\S]*RESOLVIDO/,['Enums limitam valores possíveis.','Declare ABERTO, RESOLVIDO.','Imprima Estado.RESOLVIDO.'],'O estado é uma placa que só aceita opções previstas.'),
    arenaStep('Callback de encerramento','Quando o ticket fecha, uma ação precisa rodar.','Crie Runnable com lambda e execute run() para imprimir Ticket encerrado.',missionWrap('    // Crie um Runnable com lambda e chame run().'),'Ticket encerrado',/Runnable[\s\S]*->/,['Runnable representa uma ação sem retorno.','Use () -> System.out.println(...).','Chame acao.run().'],'O callback é um recado para executar quando chegar a hora.'),
    arenaStep('Verificação de regressão','O total esperado de tickets resolvidos é 3.','Escreva uma verificação com if que lance AssertionError quando a soma 1 + 2 for diferente de 3; imprima Teste passou.',missionWrap('    int resolvidos = 1 + 2;\n    // Verifique a condição e imprima o resultado.'),'Teste passou',/\bif\s*\([\s\S]*AssertionError/,['Compare resolvidos != 3.','Dentro do if, lance new AssertionError().','Depois imprima Teste passou.'],'O teste é o alarme para uma regra que deixou de valer.')
  ]}
);
